package net.minecraft.world.entity;import net.minecraft.world.level.Level;public class Entity{public int tickCount,lastEvent;public java.util.UUID id=java.util.UUID.randomUUID();public Level world;public boolean alive=true;public double x,y,z;public Entity(Level l){world=l;}public net.minecraft.nbt.CompoundTag data=new net.minecraft.nbt.CompoundTag();public double getX(){return x;}public double getY(){return y;}public double getZ(){return z;}public net.minecraft.nbt.CompoundTag getPersistentData(){return data;}public net.minecraft.core.BlockPos blockPosition(){return new net.minecraft.core.BlockPos((int)Math.floor(x),(int)Math.floor(y),(int)Math.floor(z));}public net.minecraft.world.phys.AABB getBoundingBox(){return new net.minecraft.world.phys.AABB();}public Level level(){return world;}public boolean isAlive(){return alive;}public java.util.UUID getUUID(){return id;}public double distanceToSqr(Entity e){return (x-e.x)*(x-e.x)+(y-e.y)*(y-e.y)+(z-e.z)*(z-e.z);}public void handleEntityEvent(byte b){lastEvent=b;}}